// Character classes as the JVM answers them (CPP_PORT_PLAN.md §6.7).
//
// The lexer and a few passes call Kotlin's Char.isLetter(), isDigit(),
// isLetterOrDigit(), isWhitespace(), isLowerCase(), isUpperCase() and the case
// mappings, which accept any Unicode character. char_tables.cpp holds the
// answers of the JVM the Kotlin tests run on for all 65,536 UTF-16 units; it
// is data, generated by the oracle (oracle/CharTables.kt), not a library.
#pragma once

#include <cstdint>

namespace azora {

bool isLetter(char16_t c);
bool isDigit(char16_t c);
bool isLetterOrDigit(char16_t c);
bool isWhitespace(char16_t c);
bool isLowerCase(char16_t c);
bool isUpperCase(char16_t c);
char16_t uppercaseChar(char16_t c);
char16_t lowercaseChar(char16_t c);

inline bool isHighSurrogate(char16_t c) { return c >= 0xD800 && c <= 0xDBFF; }
inline bool isLowSurrogate(char16_t c) { return c >= 0xDC00 && c <= 0xDFFF; }
inline bool isSurrogate(char16_t c) { return c >= 0xD800 && c <= 0xDFFF; }

/** Kotlin `Char.digitToInt(radix)`, or -1 when [c] is not a digit of [radix]. */
int digitValue(char16_t c, int radix);

}  // namespace azora
